import { describe, expect, test } from "bun:test";

import { bucketOf, turnSizes, type Bucket } from "./budget-table.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	// Each lower bound is inclusive and each upper bound exclusive, so the
	// last size below a threshold and the threshold itself land in neighbours.
	const boundaries: Array<[number, Bucket]> = [
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
		[Number.MAX_SAFE_INTEGER, "huge"],
	];

	test.each(boundaries)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"%p tokens throws RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const preamble: HarnessMessage = { role: "assistant", content: "preamble before any prompt" };
	const firstPrompt: HarnessMessage = { role: "user", content: "summarise the accounting report" };
	const firstReply: HarnessMessage = { role: "assistant", content: "It covers three Conversations." };
	const secondPrompt: HarnessMessage = { role: "user", content: "and the cache share?" };
	const secondReply: HarnessMessage = { role: "assistant", content: "Zero percent on every Call." };

	test("drops the leading Turn and sizes each prompted Turn in order", () => {
		const sizes = turnSizes([preamble, firstPrompt, firstReply, secondPrompt, secondReply]);

		expect(sizes).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("keeps a Turn whose user prompt has no text", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };

		const sizes = turnSizes([preamble, firstPrompt, firstReply, emptyPrompt, secondReply]);

		expect(sizes).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([emptyPrompt, secondReply]),
		]);
	});
});

