// suite: TT-5082
import { describe, expect, test } from "bun:test";

import { weighted } from "./budget-table.ts";

describe("weighted", () => {
	// Sizes either side of each threshold, so a size weighted with its
	// neighbour bucket's weight gives a different product.
	const products: Array<[number, number]> = [
		[0, 0],
		[349, 174.5],
		[350, 350],
		[1799, 1799],
		[1800, 2250],
		[6999, 8748.75],
		[7000, 10500],
		[23999, 35998.5],
		[24000, 54000],
	];

	test.each(products)("%p tokens weighs %p", (size, product) => {
		expect(weighted([size])).toEqual([product]);
	});

	test("keeps the order of the sizes", () => {
		expect(weighted([8000, 90, 30000, 2400, 400])).toEqual([12000, 45, 67500, 3000, 400]);
	});

	test("gives an empty list for an empty list", () => {
		expect(weighted([])).toEqual([]);
	});

	test.each([-1, Number.NaN, Number.POSITIVE_INFINITY])("%p tokens throws RangeError", (size) => {
		expect(() => weighted([100, size])).toThrow(RangeError);
	});
});

