import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Turn-size bucket names, smallest to largest. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

/** Turn-size bucket. */
export type Bucket = (typeof BUCKETS)[number];

/**
 * Each bucket's upper bound, exclusive; its lower bound is the previous
 * bucket's upper bound, inclusive. `huge` has no upper bound.
 */
const BELOW: Record<Bucket, number> = {
	tiny: 350,
	small: 1800,
	medium: 7000,
	large: 24000,
	huge: Infinity,
};

/**
 * The bucket a Turn of `tokens` estimated tokens falls in.
 *
 * @throws RangeError when `tokens` is negative or not finite.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count: ${tokens}`);
	}
	for (const bucket of BUCKETS) if (tokens < BELOW[bucket]) return bucket;
	return "huge";
}

/**
 * The estimated size of each Turn in `messages`, in order, as
 * `approximateTokens` over the Turn's messages.
 *
 * The leading-Turn rule: `reconstructTurns` collects any messages that come
 * before the first user prompt into a leading Turn with no prompt. No user
 * started it, so it is not a Turn of the Conversation and gets no size.
 * Only that leading Turn can be dropped. It is recognised by its first
 * message not being a `user` message, not by an empty `prompt`: a user prompt
 * with no text also has `prompt === ""` and still starts a real Turn.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	const sizes: number[] = [];
	for (const turn of reconstructTurns(messages)) {
		// The leading Turn with no prompt; see above.
		if (turn.messages[0]?.role !== "user") continue;
		sizes.push(approximateTokens(turn.messages));
	}
	return sizes;
}

/**
 * How many of `sizes` fall in each bucket, largest bucket first. Every
 * bucket gets an entry, with count 0 when no size falls in it, except `huge`,
 * which is left out when empty.
 *
 * @throws RangeError when a size is negative or not finite, as `bucketOf`.
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return [...BUCKETS]
		.reverse()
		.map((bucket) => ({ bucket, count: counts[bucket] }))
		.filter(({ bucket, count }) => bucket !== "huge" || count > 0);
}

/** Each bucket's weight, from notes/weights.md. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * Each of `sizes` times the weight of its bucket, rounded to the nearest
 * multiple of 10 with halves rounding up (notes/rounding.md), in the same
