 * @throws RangeError when a size is negative or not finite, as `bucketOf`.
 */
export function bucketTotals(sizes: number[]): Map<Bucket, number> {
	const totals = new Map<Bucket, number>(BUCKETS.map((bucket) => [bucket, 0]));
	const products = weighted(sizes);
	sizes.forEach((size, index) => {
		const bucket = bucketOf(size);
		totals.set(bucket, (totals.get(bucket) ?? 0) + (products[index] ?? 0));
	});
	return totals;
}

/** The plain sum of `sizes`; 0 for an empty list. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

