	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1249, "1.2k"],
		[1250, "1.3k"],
		// 1.15 is not exact in binary; halves must still round up.
		[1150, "1.2k"],
		[9950, "10.0k"],
		[12000, "12.0k"],
	])("%p is shown as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

