import { describe, expect, test } from "bun:test";

import { renderTable } from "./budget-render.ts";
import {
	BUCKETS,
	bucketOf,
	bucketTotals,
	formatCount,
	histogram,
	labelOf,
	summaryLine,
	totalOf,
	turnSizes,
	type Bucket,
} from "./budget-table.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	// Each lower bound is inclusive and each upper bound exclusive, so the
	// last size below a threshold and the threshold itself land in neighbours.
	const boundaries: Array<[number, Bucket]> = [
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
		[Number.MAX_SAFE_INTEGER, "huge"],
	];

	test.each(boundaries)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"%p tokens throws RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const preamble: HarnessMessage = { role: "assistant", content: "preamble before any prompt" };
	const firstPrompt: HarnessMessage = { role: "user", content: "summarise the accounting report" };
	const firstReply: HarnessMessage = { role: "assistant", content: "It covers three Conversations." };
	const secondPrompt: HarnessMessage = { role: "user", content: "and the cache share?" };
	const secondReply: HarnessMessage = { role: "assistant", content: "Zero percent on every Call." };

	test("drops the leading Turn and sizes each prompted Turn in order", () => {
		const sizes = turnSizes([preamble, firstPrompt, firstReply, secondPrompt, secondReply]);

		expect(sizes).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("keeps a Turn whose user prompt has no text", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };

		const sizes = turnSizes([preamble, firstPrompt, firstReply, emptyPrompt, secondReply]);

		expect(sizes).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([emptyPrompt, secondReply]),
		]);
	});
});

describe("histogram", () => {
	test("counts the sample sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("keeps empty buckets at 0 but leaves out huge when no size is huge", () => {
		expect(histogram([100, 7000, 23999])).toEqual([
			{ bucket: "large", count: 2 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("gives every bucket but huge a count of 0 for an empty list", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

describe("bucketTotals", () => {
	test("sums the weighted sizes of each bucket's Turns", () => {
		// tiny 120 × 0.5 = 60 and 90 × 0.5 = 45 → 50; medium 2400 × 1.25;
		// small 400 × 1; large 8000 × 1.5; huge 24000 × 2.25.
		expect([...bucketTotals([120, 90, 2400, 400, 8000, 24000])]).toEqual([
			["tiny", 110],
			["small", 400],
			["medium", 3000],
			["large", 12000],
			["huge", 54000],
		]);
	});

	test("rounds each Turn's weighted size before summing", () => {
		// 90 × 0.5 = 45 rounds to 50 per Turn; rounding the sum would give 90.
		expect(bucketTotals([90, 90]).get("tiny")).toBe(100);
	});

	test("gives every bucket 0 for an empty list", () => {
		expect([...bucketTotals([])]).toEqual(BUCKETS.map((bucket) => [bucket, 0]));
	});

	test("throws RangeError for a negative size", () => {
		expect(() => bucketTotals([100, -1])).toThrow(RangeError);
	});
});

describe("totalOf", () => {
	test("sums the sizes, 0 for an empty list", () => {
		expect(totalOf([120, 90, 2400, 400, 8000])).toBe(11010);
		expect(totalOf([])).toBe(0);
	});
});

describe("formatCount", () => {
	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1249, "1.2k"],
		[1250, "1.3k"],
		// 1.15 is not exact in binary; halves must still round up.
		[1150, "1.2k"],
		[9950, "10.0k"],
		[12000, "12.0k"],
	])("%p is shown as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

describe("labelOf", () => {
	const labels: Array<[Bucket, string]> = [
		["tiny", "crumbs"],
		["small", "bites"],
		["medium", "meals"],
		["large", "feasts"],
		["huge", "banquets"],
	];

	test.each(labels)("%p is labelled %p", (bucket, label) => {
		expect(labelOf(bucket)).toBe(label);
	});

	test("gives every bucket a different label", () => {
		expect(new Set(BUCKETS.map(labelOf)).size).toBe(BUCKETS.length);
	});
});

describe("renderTable", () => {
	test("renders the header, then one row per histogram entry, largest bucket first", () => {
		expect(renderTable([120, 90, 2400, 400, 8000])).toEqual([
			"bucket | turns | weighted",
			"feasts | 1 | 12.0k",
			"meals | 1 | 3.0k",
			"bites | 1 | 400",
			"crumbs | 2 | 110",
		]);
	});

	test("leads with a banquets row when a size is huge", () => {
		// 24000 × 2.25 + 30000 × 2.25 = 54000 + 67500.
		expect(renderTable([24000, 30000, 100])).toEqual([
			"bucket | turns | weighted",
			"banquets | 2 | 121.5k",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 1 | 50",
		]);
	});

	test("shows a bucket's weighted total as the sum of each Turn's rounded weighted size", () => {
		// 90 × 0.5 = 45 rounds to 50 per Turn; rounding the sum would give 90.
		expect(renderTable([90, 90])).toContain("crumbs | 2 | 100");
	});

	test("renders every bucket but banquets with zeros for an empty list", () => {
		expect(renderTable([])).toEqual([
			"bucket | turns | weighted",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 0 | 0",
		]);
	});

	test("throws RangeError for a negative size", () => {
		expect(() => renderTable([100, -1])).toThrow(RangeError);
	});
});

describe("summaryLine", () => {
	test("lays out turns, unweighted total, used, peak and over joined by ' · '", () => {
		// Weighted, 8000 alone would be 12000; total stays the plain 9400.
		expect(summaryLine([400, 1000, 8000], 20000)).toBe(
			"turns=3 · total=9400 · used=47% · peak=large · over=0",
		);
	});

	test("gives zeros and peak=none for a list with no Turns", () => {
		expect(summaryLine([], 1000)).toBe("turns=0 · total=0 · used=0% · peak=none · over=0");
	});

	test("rounds used down", () => {
		// 300 / 900 = 33.3…%; 599 / 900 = 66.5…% would round to 67.
		expect(summaryLine([100, 200], 900)).toContain("used=33%");
		expect(summaryLine([599], 900)).toContain("used=66%");
	});

	test("lets used exceed 100%", () => {
		expect(summaryLine([24000], 20000)).toContain("used=120%");
	});

	test("peaks at the largest bucket holding a Turn, wherever it comes in the list", () => {
		expect(summaryLine([30000, 100, 2000], 100000)).toContain("peak=huge");
		expect(summaryLine([100, 400, 50], 100000)).toContain("peak=small");
	});

	test("counts only Turns strictly larger than 9000 as over", () => {
		expect(summaryLine([9000, 9001, 30000], 10000)).toMatch(/ · over=2$/);
	});

	test.each([0, -0, -1, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"budget %p throws RangeError",
		(budget) => {
			expect(() => summaryLine([100], budget)).toThrow(RangeError);
			expect(() => summaryLine([], budget)).toThrow(RangeError);
		},
	);

	test("throws RangeError for a negative size", () => {
		expect(() => summaryLine([100, -1], 1000)).toThrow(RangeError);
	});
});

