export function bucketTotals(sizes: number[]): Map<Bucket, number> {
…
}

/** The plain sum of `sizes`; 0 for an empty list. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

/** Separates the fields of a summary line (notes/format.md). */
const FIELD_SEPARATOR = " · ";

/** Turns strictly larger than this many tokens count towards `over=`. */
const OVER = 9000;

/**
 * The one-line summary of Turns of `sizes` against `budget`
 * (notes/format.md): `turns=`, `total=` (unweighted), `used=` as a whole
 * percentage of `budget` rounded down, then the footer from notes/buckets.md,
 * `peak=` (the largest bucket holding a Turn, `none` without Turns) and
 * `over=` (Turns strictly larger than 9000 tokens).
 *
 * @throws RangeError when `budget` is not a positive finite number, or when
 * a size is negative or not finite, as `bucketOf`.
 */
export function summaryLine(sizes: number[], budget: number): string {
	if (!Number.isFinite(budget) || budget <= 0) {
		throw new RangeError(`Budget must be a positive, finite token count: ${budget}`);
	}
	let peak: Bucket | "none" = "none";
	let over = 0;
	for (const size of sizes) {
		const bucket = bucketOf(size);
		if (peak === "none" || BUCKETS.indexOf(bucket) > BUCKETS.indexOf(peak)) peak = bucket;
		if (size > OVER) over += 1;
	}
	const total = totalOf(sizes);
	return [
		`turns=${sizes.length}`,
		`total=${total}`,
		`used=${Math.floor((total * 100) / budget)}%`,
		`peak=${peak}`,
		`over=${over}`,
	].join(FIELD_SEPARATOR);
}
